# Generated by manage.py generate_test_cases.
from django.http import HttpResponse
from django.urls import resolve, reverse
from django.utils import timezone

from bloomerp.models.tutorial import Tutorial, TutorialRevision
from bloomerp.tests.base import (
    BloomerpAPIDetailViewTestCase,
    ExpectedResult,
    RequestScenario,
)


class TestTutorialRevisionSettingsView(BloomerpAPIDetailViewTestCase):
    """Tests class `TutorialRevisionSettingsView` from `bloomerp/views/api/tutorials/revision_settings.py`."""

    view_name = "tutorial_revision_settings"
    model = TutorialRevision

    def extendedSetup(self) -> None:
        """Create a draft with a legacy path and a published revision."""
        tutorial = Tutorial.objects.create(name="Getting started")
        self.home = reverse("bloomerp_home_view")
        self.draft = TutorialRevision.objects.create(
            tutorial=tutorial, number=2, trigger_route=self.home
        )
        self.published = TutorialRevision.objects.create(
            tutorial=tutorial, number=1, published_at=timezone.now()
        )

    def create_test_object(self) -> TutorialRevision:
        """Use the draft's primary key in the settings URL by default."""
        return self.draft

    def returns_picker(self, response: HttpResponse) -> bool:
        """Check that the draft opens with its path and the Home suggestion."""
        settings = response.json()
        return (
            settings["trigger_path"] == self.home
            and settings["auto_start"] is False
            and settings["can_edit_trigger"]
            and settings["can_edit_auto_start"]
            and any(route["url"] == self.home for route in settings["routes"])
        )

    def saved_route_name(self, response: HttpResponse) -> bool:
        """Verify that playback receives a route name after saving a URL."""
        self.draft.refresh_from_db()
        return (
            self.draft.trigger_route == resolve(self.home).view_name
            and self.draft.auto_start
            and response.json()["trigger_path"] == self.home
        )

    def saved_wildcard_path(self, response: HttpResponse) -> bool:
        """Verify that the draft stores and returns the wildcard unchanged."""
        self.draft.refresh_from_db()
        return (
            self.draft.trigger_route == "/*bulk-upload"
            and self.draft.auto_start
            and response.json()["trigger_path"] == self.draft.trigger_route
        )

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Exercise picker data, validation, and access to revision settings."""
        return [
            RequestScenario(
                name="Author opens trigger settings with the shared picker choices",
                user=self.admin_user,
                expected=ExpectedResult(response_validators=self.returns_picker),
            ),
            RequestScenario(
                name="Saving a page path records its route name and auto-start",
                method="PATCH",
                user=self.admin_user,
                content_type="application/json",
                data={"trigger_path": self.home, "auto_start": True},
                expected=ExpectedResult(response_validators=self.saved_route_name),
            ),
            RequestScenario(
                name="An automatic trigger can use a local wildcard path",
                method="PATCH",
                user=self.admin_user,
                content_type="application/json",
                data={"trigger_path": "/*bulk-upload", "auto_start": True},
                expected=ExpectedResult(response_validators=self.saved_wildcard_path),
            ),
            RequestScenario(
                name="A wildcard trigger cannot point to a different host",
                method="PATCH",
                user=self.admin_user,
                content_type="application/json",
                data={"trigger_path": "//example.com/*"},
                expected=ExpectedResult(status_code=400),
            ),
            RequestScenario(
                name="Automatic playback requires a trigger page",
                method="PATCH",
                user=self.admin_user,
                content_type="application/json",
                data={"trigger_path": "", "auto_start": True},
                expected=ExpectedResult(status_code=400),
            ),
            RequestScenario(
                name="The trigger requires a local page",
                method="PATCH",
                user=self.admin_user,
                content_type="application/json",
                data={"trigger_path": "https://example.com/"},
                expected=ExpectedResult(status_code=400),
            ),
            RequestScenario(
                name="Learners cannot read an author's draft settings",
                user=self.normal_user,
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="A draft ID in the body cannot change the published URL target",
                method="PATCH",
                user=self.admin_user,
                content_type="application/json",
                view_kwargs={"pk": self.published.pk},
                data={"revision_id": str(self.draft.pk), "trigger_path": self.home},
                expected=ExpectedResult(status_code=404),
            ),
        ]
